468	/// Write-Ahead Log
469	pub struct Wal {
470	    db: *mut ffi::sqlite3,
471	    db_name: *const c_char,
472	}
473	
474	impl Wal {
475	    /// Checkpoint a database
476	    pub fn checkpoint(&self) -> Result<()> {
477	        unsafe { decode_result_raw(self.db, ffi::sqlite3_wal_checkpoint(self.db, self.db_name)) }
478	    }
479	
480	    /// Checkpoint a database
481	    pub fn checkpoint_v2(&self, mode: CheckpointMode) -> Result<(c_int, c_int)> {
482	        let mut n_log = 0;
483	        let mut n_ckpt = 0;
484	        unsafe {
485	            decode_result_raw(
486	                self.db,
487	                ffi::sqlite3_wal_checkpoint_v2(
488	                    self.db,
489	                    self.db_name,
490	                    mode as c_int,
491	                    &raw mut n_log,
492	                    &raw mut n_ckpt,
493	                ),
494	            )?;
495	        };
496	        Ok((n_log, n_ckpt))
497	    }
498	
499	    /// Name of the database that was written to
500	    #[must_use]
501	    pub fn name(&self) -> &CStr {
502	        unsafe { CStr::from_ptr(self.db_name) }
503	    }
504	}
