220	                    ffi::sqlite3_prepare_v3(
221	                        self.db(),
222	                        c_sql,
223	                        len,
224	                        flags.bits(),
225	                        &mut c_stmt,
226	                        &mut c_tail,
227	                    )
228	                }
229	            }
230	        };
