955	    fn auto_commit() -> Result<()> {
956	        use super::TransactionState;
957	        use crate::DEFAULT_NAME;
958	        let db = Connection::open_in_memory()?;
959	        db.execute_batch("CREATE TABLE t(i UNIQUE);")?;
960	        assert!(db.is_autocommit());
961	        let mut stmt = db.prepare("SELECT name FROM sqlite_master")?;
962	        assert_eq!(TransactionState::None, db.transaction_state(DEFAULT_NAME)?);
963	        {
964	            let mut rows = stmt.query([])?;
965	            assert!(rows.next()?.is_some()); // start reading
966	            assert_eq!(TransactionState::Read, db.transaction_state(DEFAULT_NAME)?);
967	            db.execute("INSERT INTO t VALUES (1)", [])?; // auto-commit
968	            assert_eq!(TransactionState::Read, db.transaction_state(DEFAULT_NAME)?);
969	            assert!(rows.next()?.is_some()); // still reading
970	            assert_eq!(TransactionState::Read, db.transaction_state(DEFAULT_NAME)?);
971	            assert!(rows.next()?.is_none()); // end
972	            assert_eq!(TransactionState::None, db.transaction_state(DEFAULT_NAME)?);
973	        }
974	        Ok(())
975	    }
