        // exclusive lock it needs in rollback journal mode
        db2.execute_batch("BEGIN")?;
        db2.query_row("SELECT x FROM foo LIMIT 1", [], |_| Ok(()))?;

        let err = {
            let mut tx = db1.transaction()?;
            tx.execute_batch("INSERT INTO foo VALUES(1)")?;
