450	    ///     let stmt = conn.prepare("SELECT * FROM test WHERE name = :example")?;
451	    ///     let index = stmt.parameter_name(1);
452	    ///     assert_eq!(index, Some(":example"));
453	    ///     Ok(())
454	    /// }
455	    /// ```
