496	    pub(crate) fn ensure_parameter_count(&self, n: usize) -> Result<()> {
497	        let count = self.parameter_count();
498	        if count == n {
499	            Ok(())
500	        } else {
501	            Err(Error::InvalidParameterCount(n, count))
502	        }
503	    }
