507	        &mut self,
508	        params: &[(S, T)],
509	    ) -> Result<()> {
510	        for (name, value) in params {
511	            let i = name.idx(self)?;
512	            let ts: &dyn ToSql = &value;
513	            self.bind_parameter(ts, i)?;
514	        }
515	        Ok(())
516	    }
