613	    // generic because many of these branches can constant fold away.
614	    fn bind_parameter<P: ?Sized + ToSql>(&self, param: &P, ndx: usize) -> Result<()> {
615	        let value = param.to_sql()?;
616	
617	        let ptr = unsafe { self.stmt.ptr() };
618	        self.conn.decode_result(match value {
619	            ToSqlOutput::Borrowed(ValueRef::Null) | ToSqlOutput::Owned(Value::Null) => {
620	                unsafe { ffi::sqlite3_bind_null(ptr, ndx as c_int) }
621	            },
622	            ToSqlOutput::Borrowed(ValueRef::Integer(i)) | ToSqlOutput::Owned(Value::Integer(i)) => {
623	                unsafe { ffi::sqlite3_bind_int64(ptr, ndx as c_int, i) }
624	            },
625	            ToSqlOutput::Borrowed(ValueRef::Real(r)) | ToSqlOutput::Owned(Value::Real(r)) => {
626	                unsafe { ffi::sqlite3_bind_double(ptr, ndx as c_int, r) }
627	            },
628	            ToSqlOutput::Borrowed(ValueRef::Text(s)) => {
629	                Self::bind_text(ptr, ndx, s)
630	            },
631	             ToSqlOutput::Owned(Value::Text(s)) => {
632	                Self::bind_text(ptr, ndx, s.as_bytes())
633	            },
634	            ToSqlOutput::Borrowed(ValueRef::Blob(b)) => {
635	                Self::bind_blob(ptr, ndx, b)
636	            },
637	            ToSqlOutput::Owned(Value::Blob(b)) => {
638	                Self::bind_blob(ptr, ndx, b.as_slice())
639	            },
640	            #[cfg(feature = "blob")]
641	            ToSqlOutput::ZeroBlob(len) => {
642	                unsafe {
643	                    ffi::sqlite3_bind_zeroblob64(ptr, ndx as c_int, len)
644	                }
645	            }
646	            #[cfg(feature = "functions")]
647	            ToSqlOutput::Arg(_) => {
648	                return Err(err!(ffi::SQLITE_MISUSE, "Unsupported value \"{value:?}\""));
649	            }
650	            #[cfg(feature = "pointer")]
651	            ToSqlOutput::Pointer(p) => {
652	                unsafe {
653	                    ffi::sqlite3_bind_pointer(ptr, ndx as c_int, p.0.cast_mut(), p.1.as_ptr(), p.2)
654	                }
655	            }
656	        })
657	    }
658	
659	    fn bind_text(stmt: *mut sqlite3_stmt, ndx: usize, s: &[u8]) -> c_int {
660	        unsafe {
661	            let (c_str, len, destructor) = str_for_sqlite(s);
662	            ffi::sqlite3_bind_text64(
663	                stmt,
664	                ndx as c_int,
665	                c_str,
666	                len,
667	                destructor,
668	                ffi::SQLITE_UTF8 as _, // TODO SQLITE_UTF8_ZT
669	            )
670	        }
671	    }
672	
673	    fn bind_blob(stmt: *mut sqlite3_stmt, ndx: usize, b: &[u8]) -> c_int {
674	        unsafe {
675	            let length = b.len();
676	            if length == 0 {
677	                ffi::sqlite3_bind_zeroblob64(stmt, ndx as c_int, 0)
678	            } else {
679	                ffi::sqlite3_bind_blob64(
680	                    stmt,
681	                    ndx as c_int,
682	                    b.as_ptr().cast::<c_void>(),
683	                    length as ffi::sqlite3_uint64,
684	                    ffi::SQLITE_TRANSIENT(),
685	                )
686	            }
687	        }
688	    }
