690	    #[inline]
691	    fn execute_with_bound_parameters(&mut self) -> Result<usize> {
692	        self.check_update()?;
693	        let r = self.stmt.step();
694	        let rr = self.stmt.reset();
695	        match r {
696	            ffi::SQLITE_DONE => match rr {
697	                ffi::SQLITE_OK => Ok(self.conn.changes() as usize),
698	                _ => Err(self.conn.decode_result(rr).unwrap_err()),
699	            },
700	            ffi::SQLITE_ROW => Err(Error::ExecuteReturnedResults),
701	            _ => Err(self.conn.decode_result(r).unwrap_err()),
702	        }
703	    }
704	
705	    #[inline]
706	    fn finalize_(&mut self) -> Result<()> {
707	        let mut stmt = unsafe { RawStatement::new(ptr::null_mut()) };
708	        mem::swap(&mut stmt, &mut self.stmt);
709	        self.conn.decode_result(stmt.finalize())
710	    }
