712	    #[inline]
713	    #[allow(clippy::unnecessary_wraps)]
714	    fn check_update(&self) -> Result<()> {
715	        cfg_select! {
716	            feature = "extra_check" => {
717	                if self.column_count() > 0 && self.stmt.readonly() {
718	                    return Err(Error::ExecuteReturnedResults);
719	                }
720	            }
721	            _ => {}
722	        }
723	        Ok(())
724	    }
