812	
813	    pub(super) fn value_ref(&self, col: usize) -> ValueRef<'_> {
814	        let raw = unsafe { self.stmt.ptr() };
815	
816	        match self.stmt.column_type(col) {
817	            ffi::SQLITE_NULL => ValueRef::Null,
818	            ffi::SQLITE_INTEGER => {
819	                ValueRef::Integer(unsafe { ffi::sqlite3_column_int64(raw, col as c_int) })
820	            }
821	            ffi::SQLITE_FLOAT => {
822	                ValueRef::Real(unsafe { ffi::sqlite3_column_double(raw, col as c_int) })
823	            }
824	            ffi::SQLITE_TEXT => {
825	                let s = unsafe {
826	                    // Quoting from "Using SQLite" book:
827	                    // To avoid problems, an application should first extract the desired type using
828	                    // a sqlite3_column_xxx() function, and then call the
829	                    // appropriate sqlite3_column_bytes() function.
830	                    let text = ffi::sqlite3_column_text(raw, col as c_int);
831	                    let len = ffi::sqlite3_column_bytes(raw, col as c_int);
832	                    assert!(
833	                        !text.is_null(),
834	                        "unexpected SQLITE_TEXT column type with NULL data"
835	                    );
836	                    from_raw_parts(text.cast::<u8>(), len as usize)
837	                };
838	
839	                ValueRef::Text(s)
840	            }
841	            ffi::SQLITE_BLOB => {
842	                let (blob, len) = unsafe {
843	                    (
844	                        ffi::sqlite3_column_blob(raw, col as c_int),
845	                        ffi::sqlite3_column_bytes(raw, col as c_int),
846	                    )
847	                };
848	
849	                assert!(
850	                    len >= 0,
851	                    "unexpected negative return from sqlite3_column_bytes"
852	                );
853	                if len > 0 {
854	                    assert!(
855	                        !blob.is_null(),
856	                        "unexpected SQLITE_BLOB column type with NULL data"
857	                    );
858	                    ValueRef::Blob(unsafe { from_raw_parts(blob.cast::<u8>(), len as usize) })
859	                } else {
860	                    // The return value from sqlite3_column_blob() for a zero-length BLOB
861	                    // is a NULL pointer.
862	                    ValueRef::Blob(&[])
863	                }
864	            }
865	            _ => unreachable!("sqlite3_column_type returned invalid value"),
866	        }
867	    }
868	
869	    #[inline]
870	    pub(super) fn step(&self) -> Result<bool> {
871	        match self.stmt.step() {
872	            ffi::SQLITE_ROW => Ok(true),
873	            ffi::SQLITE_DONE => Ok(false),
874	            code => Err(self.conn.decode_result(code).unwrap_err()),
875	        }
876	    }
877	
878	    #[inline]
879	    pub(super) fn reset(&self) -> Result<()> {
880	        match self.stmt.reset() {
881	            ffi::SQLITE_OK => Ok(()),
882	            code => Err(self.conn.decode_result(code).unwrap_err()),
883	        }
884	    }
885	}
