887	/// Prepared statement status counters.
888	///
889	/// See `https://www.sqlite.org/c3ref/c_stmtstatus_counter.html`
890	/// for explanations of each.
891	///
892	/// Note that depending on your version of SQLite, all of these
893	/// may not be available.
894	#[repr(i32)]
895	#[derive(Clone, Copy, PartialEq, Eq)]
896	#[non_exhaustive]
897	pub enum StatementStatus {
898	    /// Equivalent to `SQLITE_STMTSTATUS_FULLSCAN_STEP`
899	    FullscanStep = 1,
